import pathlib,subprocess,json,os
home=pathlib.Path('/home/appontrack')
targets=['public_html','.ontrack-saas','.ontrack-mobile','ontrack-voice-link','backup']
names=[]
for item in home.iterdir():
 if item.is_dir() and (item.name.startswith('.ontrack') or item.name.lower() in ['public_html','ontrack-voice-link','backup','mail','etc','ssl']):
  names.append(item.name)
def size(p):
 try:
  a=subprocess.run(['/usr/bin/du','-sk',str(p)],capture_output=True,text=True,timeout=18)
  return int(a.stdout.split()[0]) if a.returncode==0 else None
 except Exception:return None
print(json.dumps({'paths_kib':{v:size(home/v) for v in targets},'notable_dirs':names,'home_writable':os.access(home,os.W_OK),'backup_exists':(home/'backup').exists()}))
